tau_r = 1
tau_s = 1
for a in exps:
    tau_r *= (r * a + 1)
    tau_s *= (s * a + 1)
# Divisors of n^r less than n^{r/2}
total_less = (tau_r - 1) // 2  # integer because n^r is a perfect square
# Divisors of n^s less than n^{r/2}
subtract = tau_s if s < (r // 2) else (tau_s - 1)
answer = total_less - subtract
# Difficulty and sanity checks
if answer < 1:
    return (False, None)  # Trivial or invalid instance; generator should avoid
if answer < 50:
